//true if Cut-to-Print (CTP) concentricty is out of range in X direction (CD) or Y direction (MD)
   {[.]CTPdeviationCrossDirection} > {[.]CTPdeviationCDUpperLimit}
|| {[.]CTPdeviationCrossDirection} < {[.]CTPdeviationCDlowerLimit}
|| {[.]CTPdeviationMachineDirection} > {[.]CTPdeviationMDupperLimit}
|| {[.]CTPdeviationMachineDirection} < {[.]CTPdeviationMDlowerLimit}

//If the Cut-to-Print (CTP) is out of range, ignore Orange Tab Size out of range.
({[.]OrangeTabSize} < {[.]OrangeTabSizeLowerLimit}
|| {[.]OrangeTabSize} > {[.]OrangeTabSizeUpperLimit})
&& !{[.]CTPoutofrange}
